// Brochure PDFs, generated by scripts/build-brochures.mjs into public/downloads/.
export type BrochureKind = 'brands' | 'retailers';
export const brochureKinds: BrochureKind[] = ['brands', 'retailers'];
export const brochurePath = (kind: BrochureKind, lang: string) => `/downloads/${kind}-${lang}.pdf`;
